class PcapPacket(object):

    def __init__(self, pdml_log_entry):
        self._pdml_log_entry = pdml_log_entry

    def __getattr__(self, name):
        if name in self._pdml_log_entry.packet.keys():
            name += "$"
            return self._pdml_log_entry.packet.findall(name)
        raise KeyError(self._pdml_log_entry.packet.keys())

    def get_field_value_by_name(self, name, attribute="show"):
        fields = getattr(self, name)
        return self._extract_field_attribute_from_fields(fields, attribute)

    def get_field_value_by_xpath(self, xpath, attribute="show"):
        fields = self._pdml_log_entry.packet.xpath(xpath)
        return self._extract_field_attribute_from_fields(fields, attribute)

    @staticmethod
    def _extract_field_attribute_from_fields(fields, attribute):
        return [getattr(each_field, attribute) for each_field in fields]
